var draw = SVG().addTo(document.getElementById('container')).size('100%','100%');
draw.viewbox(0, 0, 600, 280);
var scene = draw.group();
var CW = 72, X0 = 100, Y0 = 70, CH = 56;
function cellCx(k) { return X0 + (k - 0.5) * CW; }

function arcPath(a, b, color, width, dash) {
  var x1 = cellCx(a), x2 = cellCx(b), y = Y0 + CH + 14;
  var depth = 16 + 14 * Math.abs(b - a);
  var p = scene.path('M ' + x1 + ' ' + y + ' Q ' + ((x1 + x2) / 2) + ' ' + (y + 2 * depth) + ' ' + x2 + ' ' + (y + 4))
    .fill('none').stroke({ color: color, width: width });
  if (dash) p.attr('stroke-dasharray', dash);
  scene.polygon([x2, y - 4, x2 - 6, y + 8, x2 + 6, y + 8].join(' ')).fill(color);
}

function renderScene(m) {
  scene.clear();
  scene.text(m.label || '').move(28, Y0 + CH / 2 - 14).font({ size: 22, style: 'italic', family: 'serif' });
  for (var k = 1; k <= 6; k++) {
    var fill = '#fff';
    if (m.keyIdx === k) fill = '#000';
    else if (k <= m.prefix) fill = '#c8c8c8';
    scene.rect(CW, CH).move(X0 + (k - 1) * CW, Y0).fill(fill).stroke({ color: '#000', width: 1.5 });
    scene.text(String(k)).move(cellCx(k) - 4, Y0 - 28).font({ size: 17, family: 'serif' });
    var t = scene.text(String(m.values[k - 1]))
      .font({ size: 24, family: 'serif', weight: m.keyIdx === k ? 'bold' : 'normal' })
      .fill(m.keyIdx === k ? '#fff' : '#000');
    t.move(cellCx(k) - t.bbox().width / 2, Y0 + CH / 2 - t.bbox().height / 2);
  }
  (m.grayArcs || []).forEach(function (pr) { arcPath(pr[0], pr[1], '#999', 1.5); });
  if (m.boldArc) arcPath(m.boldArc[0], m.boldArc[1], '#000', 2.5);
}

