}
function frameFirst() { showFrame(0); }
function framePrev() { showFrame(fIdx - 1); }
function frameNext() { showFrame(fIdx + 1); }
function startPlay() {
  playing = true;
  playTimer = setInterval(function () {
    if (fIdx >= frames.length - 1) { stopPlay(); return; }
    showFrame(fIdx + 1);
  }, playDelay);
}
function stopPlay() { playing = false; clearInterval(playTimer); }
function framePlay() { if (!frames.length) return; playing ? stopPlay() : startPlay(); }

/* ── Run student code in a Web Worker ── */
function trigger_run() {
  stopPlay();
  var code = document.getElementById('insertionSortEditorCode').value;
  var raw = document.getElementById('arrayInput').value.split(',').map(function (s) { return +s.trim(); });
  var status = document.getElementById('runStatus');
  if (raw.length !== 6 || raw.some(function (v) { return !isFinite(v); })) {
    status.textContent = 'status: error — need exactly 6 numbers'; return;
  }
  document.getElementById('runBtn').disabled = true;
  status.textContent = 'status: running…';

  var harness =
    "var A=[0].concat(" + JSON.stringify(raw) + ");\n" +
    "var frames=[],curKey=0,keyPos=0,keyVal=0,hole=0,curSorted=0,ops=0;\n" +
    "function chk(i){if(i<1||i>6)throw new Error('index '+i+' out of range 1..6');}\n" +
    "function push(kind,idx,msg){if(frames.length>=600)throw new Error('frame cap (600) hit');" +
    "frames.push({kind:kind,state:A.slice(),indices:idx,message:msg,keyIdx:curKey,sortedUpTo:curSorted});}\n" +
    "function tick(){if(++ops>5000)throw new Error('operation cap hit');}\n" +
    "function key(i){tick();chk(i);curKey=i;keyPos=i;keyVal=A[i];hole=i;push('key',[i],'key = A['+i+'] = '+A[i]);}\n" +
    "function compare(i,j){tick();chk(i);chk(j);var vj=(j===keyPos&&curKey===j)?keyVal:A[j];" +
    "var r=A[i]>vj;push('compare',[i,j],'compare A['+i+']='+A[i]+' with A['+j+']='+vj+' → '+r);return r;}\n" +
    "function shift(i){tick();chk(i);A[i+1]=A[i];hole=i;push('shift',[i,i+1],'shift A['+i+']='+A[i+1]+' one slot right');}\n" +
    "function markSorted(i){tick();chk(i);A[hole]=keyVal;curSorted=i;curKey=0;push('markSorted',[i],'A['+i+'] inserted — sorted prefix now covers 1..'+i);}\n" +
    "function note(t){tick();push('note',[],String(t));}\n" +
    "try{\n" + code + "\n" +
    "if(typeof insertionSort!=='function')throw new Error('entry point insertionSort(A) not found');\n" +
    "insertionSort(A);\n" +
    "postMessage({frames:frames,final:A.slice(1),error:null});\n" +
    "}catch(e){postMessage({frames:frames,final:A.slice(1),error:String(e&&e.message||e)});}";

  var blob = new Blob([harness], { type: 'text/javascript' });
  var url = URL.createObjectURL(blob);
  var w = new Worker(url);
  var done = false;
  var to = setTimeout(function () {
    if (done) return; done = true; w.terminate(); URL.revokeObjectURL(url);
    finishRun(framesFromError('timeout: took longer than 2s'), null, 'timeout after 2s');
  }, 2000);
  function framesFromError(msg) { return [{ kind: 'note', state: [0].concat(raw), indices: [], message: msg, keyIdx: 0, sortedUpTo: 0 }]; }
  w.onmessage = function (e) {
    if (done) return; done = true; clearTimeout(to); w.terminate(); URL.revokeObjectURL(url);
    finishRun(e.data.frames, e.data.final, e.data.error);
  };
  w.onerror = function (e) {
    if (done) return; done = true; clearTimeout(to); w.terminate(); URL.revokeObjectURL(url);
    finishRun(framesFromError('error: ' + (e.message || 'unknown')), null, e.message);
  };

  function finishRun(fr, finalArr, err) {
    document.getElementById('runBtn').disabled = false;
    frames = fr.length ? fr : framesFromError(err || 'no frames produced');
    fIdx = -1; showFrame(0);
    if (err) { status.textContent = 'status: error — ' + err; return; }
    var sorted = finalArr && finalArr.every(function (v, i) { return i === 0 || finalArr[i - 1] <= v; });
    status.textContent = sorted ? 'status: ✓ correct — ' + finalArr.join(', ') :
      'status: ✗ wrong answer — final array ' + (finalArr ? finalArr.join(', ') : '?');
  }
}

showDemo();
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Insertion sort grows a sorted prefix one key at a time by comparing the key leftward and shifting larger elements right until the key's correct slot is found.
KEY INSIGHT (what students should walk away understanding): Each key only needs to travel left past the elements larger than itself — the number of shifts per key is exactly the number of inversions it participates in, which is why already-nearly-sorted input is cheap.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
