var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 600, 300);
var scene = draw.group();
var CW = 72, X0 = 88, Y0 = 64, CH = 56;
var yBase = Y0 + CH + 12;
function cellCx(k) { return X0 + (k - 0.5) * CW; }

function arrowHead(x, y, color) {
  scene.polygon([x, y - 7, x - 5, y + 4, x + 5, y + 4].join(' ')).fill(color);
}
/* Shallow gray arc: one element shifting a single slot right. */
function grayArc(a, b) {
  var x1 = cellCx(a) + 8, x2 = cellCx(b) - 4, y = yBase, d = 20;
  scene.path('M ' + x1 + ' ' + y + ' Q ' + ((x1 + x2) / 2) + ' ' + (y + 2 * d) + ' ' + x2 + ' ' + y)
    .fill('none').stroke({ color: '#9a9a9a', width: 1.5 });
  arrowHead(x2, y, '#9a9a9a');
}
/* Bold black arc: the key travelling to its insertion slot; depth grows with distance. */
function boldArc(j, k) {
  var x1 = cellCx(j) - 2, x2 = cellCx(k), y = yBase, d = 22 + 20 * (j - k);
  scene.path('M ' + x1 + ' ' + (y + 2) + ' Q ' + ((x1 + x2) / 2) + ' ' + (y + 2 * d) + ' ' + x2 + ' ' + (y + 2))
    .fill('none').stroke({ color: '#000', width: 2.5 });
  arrowHead(x2, y, '#000');
}
/* Collapsed loop: key compared once, nothing shifted — arrow folds back on itself. */
function collapsedArc(k) {
  var cx = cellCx(k), y = yBase;
  scene.path('M ' + (cx + 16) + ' ' + (y + 2) + ' Q ' + (cx + 36) + ' ' + (y + 48) + ' ' + (cx + 1) + ' ' + (y + 2))
    .fill('none').stroke({ color: '#000', width: 2 });
  arrowHead(cx + 1, y, '#000');
}

function renderScene(m) {
  scene.clear();
  var lab = scene.text(m.label || '').move(14, Y0 + CH / 2 - 16)
    .font({ size: 22, style: 'italic', family: 'Times New Roman, serif' });
  if (m.label) {
    lab.css('cursor', 'pointer');
    lab.on('mousemove', function (e) { showTooltip('Panel ' + m.label + ' — click for the key insight', e); });
    lab.on('mouseleave', function () { hideTooltip(); });
    lab.on('click', function () {
      showPopup('Why insertion sort is cheap on nearly-sorted input',
        'Each key travels left past only the elements larger than itself, so the number of shifts for a key equals the number of inversions it participates in. Total work is proportional to n plus the number of inversions — already-nearly-sorted input costs almost nothing.');
    });
  }
  for (var k = 1; k <= 6; k++) {
    var isKey = (m.keyIdx === k);
    var isGray = (m.gray || []).indexOf(k) >= 0;
    var fill = isKey ? '#000' : (isGray ? '#c6c6c6' : '#fff');
    var r = scene.rect(CW, CH).move(X0 + (k - 1) * CW, Y0).fill(fill).stroke({ color: '#000', width: 1.5 });
    var role = isKey ? 'the key — value being inserted this pass'
      : isGray ? 'examined this pass (compared with the key)'
      : (m.sortedNote && k <= m.sortedNote ? 'in final sorted position' : 'not yet examined');
    (function (k, rect, role) {
      rect.css('cursor', 'pointer');
      rect.on('mousemove', function (e) { showTooltip('A[' + k + '] = ' + m.values[k - 1] + ' — ' + role, e); });
      rect.on('mouseleave', function () { hideTooltip(); });
      rect.on('click', function () {
        showPopup('Cell A[' + k + ']', 'Value ' + m.values[k - 1] + ': ' + role +
          '. Insertion sort grows a sorted prefix one key at a time — the key is compared leftward and every larger element shifts one slot right until the key\u2019s slot is found.');
      });
    })(k, r, role);
    scene.text(String(k)).move(cellCx(k) - 4, Y0 - 26).font({ size: 17, family: 'Times New Roman, serif' });
    var t = scene.text(String(m.values[k - 1]))
      .font({ size: 26, family: 'Times New Roman, serif', weight: isKey ? 'bold' : 'normal' })
      .fill(isKey ? '#fff' : '#000');
    t.move(cellCx(k) - t.bbox().width / 2, Y0 + CH / 2 - t.bbox().height / 2);
  }
  (m.grayArcs || []).forEach(function (pr) { grayArc(pr[0], pr[1]); });
  if (m.boldArc) boldArc(m.boldArc[0], m.boldArc[1]);
  if (m.collapsedAt) collapsedArc(m.collapsedAt);
  (m.violate || []).forEach(function (k) {
    scene.rect(CW, CH).move(X0 + (k - 1) * CW, Y0).fill('none').stroke({ color: '#c00000', width: 3 });
  });
}

/* ── Demo steps: the complete six-panel sequence (a)–(f) ── */
var demoModels = [
  { values: [5, 2, 4, 6, 1, 3], gray: [1], keyIdx: 2, grayArcs: [[1, 2]], boldArc: [2, 1], label: '(a)',
    title: 'Key 2 moves one slot',
