  { values: [2, 5, 4, 6, 1, 3], gray: [1, 2], keyIdx: 3, grayArcs: [[2, 3]], boldArc: [3, 2], label: '(b)',
    title: 'Key 4 moves one slot',
    narration: 'With 2 and 5 sorted, key 4 is compared with 5: 5 shifts right and 4 lands in slot 2 — panel (b). Each pass grows the sorted prefix by exactly one element.' },
  { values: [2, 4, 5, 6, 1, 3], gray: [3], keyIdx: 4, grayArcs: [], boldArc: null, collapsedAt: 4, label: '(c)',
    title: 'Key 6 needs no shift',
    narration: 'When the key (6) is larger than everything in the sorted prefix, the first comparison fails and zero shifts occur — panel (c) shows the arrow collapsing.' },
  { values: [2, 4, 5, 6, 1, 3], gray: [1, 2, 3, 4], keyIdx: 5, grayArcs: [[1, 2], [2, 3], [3, 4], [4, 5]], boldArc: [5, 1], label: '(d)',
    title: 'Key 1 sweeps the whole prefix',
    narration: 'Key 1 is smaller than all four sorted elements, so four consecutive shifts ripple rightward before it lands in slot 1 — the long arrow chain of panel (d).' },
  { values: [1, 2, 4, 5, 6, 3], gray: [2, 3, 4, 5], keyIdx: 6, grayArcs: [[3, 4], [4, 5], [5, 6]], boldArc: [6, 3], label: '(e)',
    title: 'Key 3 hops three slots',
    narration: 'Key 3 is smaller than 6, 5 and 4 — three shifts ripple right — but larger than 2, so the comparisons stop and 3 lands in slot 3: panels (d) to (e). Only elements greater than the key ever move.' },
  { values: [1, 2, 3, 4, 5, 6], gray: [], keyIdx: 0, grayArcs: [], boldArc: null, label: '(f)', sortedNote: 6,
    title: 'Sorted',
    narration: 'After key 3 is inserted, the array reads 1, 2, 3, 4, 5, 6 — panel (f). Each key shifted once per larger element to its left: the total cost is exactly the number of inversions.' }
];
var demoIdx = 0;
function showDemo() {
  stopPlay();
  var m = demoModels[demoIdx];
  renderScene(m);
  document.getElementById('demoTitle').textContent = m.title;
  document.getElementById('demoNarration').textContent = m.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (demoIdx + 1) + ' / ' + demoModels.length;
  document.getElementById('frameCaption').textContent = '';
}
function nextStep() { demoIdx = Math.min(demoModels.length - 1, demoIdx + 1); showDemo(); }
function prevStep() { demoIdx = Math.max(0, demoIdx - 1); showDemo(); }

/* ── Code editor samples ── */
var SAMPLES = {
  sample: "function insertionSort(A) {\n  for (let j = 2; j <= 6; j++) {\n    key(j);\n    let i = j - 1;\n    while (i >= 1 && compare(i, j)) {\n      shift(i);\n      i = i - 1;\n    }\n    markSorted(j);\n  }\n}",
  buggy: "function insertionSort(A) {\n  for (let j = 2; j <= 6; j++) {\n    key(j);\n    let i = j - 1;\n    // BUG: forces one shift even when the\n    // first comparison already fails\n    while (i >= 1 && compare(i, j) || i === j - 1) {\n      shift(i);\n      i = i - 1;\n    }\n    markSorted(j);\n  }\n}",
  bare: "function insertionSort(A) {\n  // API: key(i), compare(i,j), shift(i), markSorted(i), note(text)\n  // shift(i) is the ONLY way to reorder elements.\n\n}"
};
function loadSample(which) { document.getElementById('insertionSortEditorCode').value = SAMPLES[which]; }
loadSample('sample');

/* ── Replay state ── */
var frames = [], fIdx = -1, playing = false, playTimer = null, playDelay = 450;
function setSpeed(v) { playDelay = +v; if (playing) { stopPlay(); startPlay(); } }
function frameToModel(f) {
  var m = { values: f.state.slice(1), gray: [], keyIdx: f.keyIdx || 0, grayArcs: [], boldArc: null, label: '' };
  if (f.kind === 'compare') m.gray = f.indices.slice();
  else if (f.kind === 'shift') { m.gray = [f.indices[0]]; m.grayArcs = [[f.indices[0], f.indices[1]]]; }
  else if (f.kind === 'markSorted') { for (var k = 1; k <= f.indices[0]; k++) m.gray.push(k); }
  else if (f.kind === 'done') { m.gray = [1, 2, 3, 4, 5, 6]; m.sortedNote = 6; }
  else if (f.kind === 'verdict') { m.violate = f.indices; }
  return m;
}
function showFrame(i) {
  if (!frames.length) return;
  fIdx = Math.max(0, Math.min(frames.length - 1, i));
  var f = frames[fIdx];
  renderScene(frameToModel(f));
  document.getElementById('frameCaption').textContent = f.message || '';
  document.getElementById('frameCounter').textContent = (fIdx + 1) + ' of ' + frames.length;
  var log = document.getElementById('frameLog');
  var kids = log.children;
  for (var n = 0; n < kids.length; n++) kids[n].style.background = (n === fIdx) ? '#c8e6ff' : '';
  if (kids[fIdx]) log.scrollTop = Math.max(0, kids[fIdx].offsetTop - log.clientHeight / 2);
}
function frameFirst() { showFrame(0); }
function framePrev() { showFrame(fIdx - 1); }
function frameNext() { showFrame(fIdx + 1); }
function startPlay() {
  playing = true;
  playTimer = setInterval(function () {
    if (fIdx >= frames.length - 1) { stopPlay(); return; }
    showFrame(fIdx + 1);
  }, playDelay);
}
function stopPlay() { playing = false; clearInterval(playTimer); }
function framePlay() { if (!frames.length) return; playing ? stopPlay() : startPlay(); }
function buildLog() {
  var log = document.getElementById('frameLog');
  log.innerHTML = '';
  frames.forEach(function (f, i) {
    var div = document.createElement('div');
    div.textContent = (i + 1) + '. ' + (f.message || f.kind);
    div.style.cssText = 'padding:1px 2px;cursor:pointer;white-space:nowrap;overflow:hidden;text-overflow:ellipsis';
    div.onclick = function () { stopPlay(); showFrame(i); };
    log.appendChild(div);
  });
}

/* ── Run student code in a Web Worker ── */
function trigger_run() {
  stopPlay();
  var code = document.getElementById('insertionSortEditorCode').value;
  var raw = document.getElementById('arrayInput').value.split(',').map(function (s) { return +s.trim(); });
  var status = document.getElementById('runStatus');
  if (raw.length !== 6 || raw.some(function (v) { return !isFinite(v); })) {
    status.textContent = 'status: error — need exactly 6 numbers'; return;
  }
  document.getElementById('runBtn').disabled = true;
  status.textContent = 'status: running…';

  var harness =
    "var realA=[0].concat(" + JSON.stringify(raw) + ");\n" +
    "var A=new Proxy(realA,{set:function(t,k,v){if(k==='length'){t[k]=v;return true;}" +
    "throw new Error('direct write to A['+String(k)+'] blocked — shift(i) is the only way to reorder elements');}});\n" +
    "var frames=[],curKey=0,keyPos=0,keyVal=0,hole=0,ops=0;\n" +
    "function chk(i){if(i<1||i>6)throw new Error('index '+i+' out of range 1..6');}\n" +
    "function push(kind,idx,msg){if(frames.length>=600)throw new Error('frame cap (600) hit');" +
    "frames.push({kind:kind,state:realA.slice(),indices:idx,message:msg,keyIdx:curKey});}\n" +
    "function tick(){if(++ops>5000)throw new Error('operation cap (5000) hit');}\n" +
    "function key(i){tick();chk(i);curKey=i;keyPos=i;keyVal=realA[i];hole=i;push('key',[i],'key = A['+i+'] = '+realA[i]);}\n" +
    "function compare(i,j){tick();chk(i);chk(j);var vj=(j===keyPos&&curKey>0)?keyVal:realA[j];" +
    "var r=realA[i]>vj;push('compare',[i,j],'compare A['+i+']='+realA[i]+' with A['+j+']='+vj+' → '+r);return r;}\n" +
    "function shift(i){tick();chk(i);realA[i+1]=realA[i];hole=i;push('shift',[i,i+1],'shift A['+i+']='+realA[i+1]+' one slot right');}\n" +
    "function markSorted(i){tick();chk(i);realA[hole]=keyVal;curKey=0;push('markSorted',[i],'key '+keyVal+' inserted at slot '+hole+' — sorted prefix now covers 1..'+i);}\n" +
    "function note(t){tick();push('note',[],String(t));}\n" +
    "try{\n" + code + "\n" +
    "if(typeof insertionSort!=='function')throw new Error('entry point insertionSort(A) not found');\n" +
    "insertionSort(A);\n" +
    "postMessage({frames:frames,final:realA.slice(1),error:null});\n" +
    "}catch(e){postMessage({frames:frames,final:realA.slice(1),error:String(e&&e.message||e)});}";

  var blob = new Blob([harness], { type: 'text/javascript' });
  var url = URL.createObjectURL(blob);
  var w = new Worker(url);
  var done = false;
  function framesFromError(msg) {
    return [{ kind: 'note', state: [0].concat(raw), indices: [], message: msg, keyIdx: 0 }];
  }
  var to = setTimeout(function () {
    if (done) return; done = true; w.terminate(); URL.revokeObjectURL(url);
    finishRun(framesFromError('timeout: took longer than 2s'), null, 'timeout after 2s');
  }, 2000);
  w.onmessage = function (e) {
    if (done) return; done = true; clearTimeout(to); w.terminate(); URL.revokeObjectURL(url);
    finishRun(e.data.frames, e.data.final, e.data.error);
  };
  w.onerror = function (e) {
    if (done) return; done = true; clearTimeout(to); w.terminate(); URL.revokeObjectURL(url);
    finishRun(framesFromError('error: ' + (e.message || 'unknown')), null, e.message || 'unknown error');
  };

  function finishRun(fr, finalArr, err) {
    document.getElementById('runBtn').disabled = false;
    frames = (fr && fr.length) ? fr : framesFromError(err || 'no frames produced');
    if (err) {
      status.textContent = 'status: error — ' + err;
    } else {
      var sorted = finalArr && finalArr.every(function (v, i) { return i === 0 || finalArr[i - 1] <= v; });
      if (sorted) {
        frames.push({ kind: 'done', state: [0].concat(finalArr), indices: [],
          message: 'final array: ' + finalArr.join(', ') + ' — sorted ✓', keyIdx: 0 });
        status.textContent = 'status: ✓ correct — ' + finalArr.join(', ');
      } else if (finalArr) {
        var bad = [];
        for (var i = 1; i < finalArr.length; i++) {
          if (finalArr[i - 1] > finalArr[i]) {
            if (bad.indexOf(i) < 0) bad.push(i);
            if (bad.indexOf(i + 1) < 0) bad.push(i + 1);
          }
        }
        frames.push({ kind: 'verdict', state: [0].concat(finalArr), indices: bad,
          message: '✗ not sorted: the red-outlined cells are out of order (A[' + bad[0] + ']=' + finalArr[bad[0] - 1] + ' is too big)', keyIdx: 0 });
        status.textContent = 'status: ✗ wrong answer — final array ' + finalArr.join(', ');
      }
    }
    buildLog();
    fIdx = -1;
    showFrame(0);
  }
}

showDemo();
window.__markRendered();
// @FIGURE_CODE_END

